export function groupAnagrams(words          )             {
const groups=new Map                 ();for(const w of words){const key=[...w].sort().join("");if(!groups.has(key))groups.set(key,[]);groups.get(key) .push(w);}return [...groups.values()].map(g=>g.sort()).sort((a,b)=>{for(let i=0;i<Math.min(a.length,b.length);i++)if(a[i]!==b[i])return a[i]<b[i]?-1:1;return a.length-b.length;});
}

